CREATE TABLE `company` (
  `Company_ID` int NOT NULL AUTO_INCREMENT,
  `Company_Name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'Unnamed',
  `Country_Code` varchar(5) DEFAULT NULL,
  `Company_No` varchar(20) DEFAULT NULL,
  `Company_Email` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `Note_ID` int DEFAULT NULL,
  `Status` enum('Active','Inactive','Lead') NOT NULL,
  `Is_Pinned` tinyint(1) DEFAULT '0',
  `Closed_Date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`Company_ID`),
  KEY `Note_ID` (`Note_ID`),
  CONSTRAINT `company_ibfk_1` FOREIGN KEY (`Note_ID`) REFERENCES `notes` (`Note_ID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
